// Change the shared chat host without archiving, clearing GPS or starting a new conversation.
function switchConversationModule(key){
 if(!['assistant','maps','travel'].includes(key))return;
 if(key==='assistant'){if(state.currentView!=='assistant'){state.currentModule=null;showView('assistant')}return}
 if(state.currentView==='module'&&state.currentModule===key)return;
 const m=MODULES[key];if(!m)return;
 state.currentModule=key;
 $('moduleTitle').textContent=UI_TEXT[state.language]?.moduleTitle?.[key]||m.title;
 $('moduleLead').textContent=localizedModuleLead(key);$('moduleContent').innerHTML='';
 $('moduleQuickLayer').classList.remove('open');$('moduleQuickLayer').setAttribute('aria-hidden','true');
 state.moduleSearchGeneration++;state.moduleSearchBusy=false;
 showView('module');
 renderModuleLandingChoices();
}
// Navigation handoff preserves the source module and its original place list.
function rememberNavigationSource(place=null){
 state.navigationReturnContext={view:state.currentView,module:state.currentModule,encyclopediaArticle:state.encyclopediaTripActive?state.lastEncyclopediaArticle||null:null,
  results:Array.isArray(state.moduleSearchResults)?state.moduleSearchResults.slice():[],
  choice:state.moduleSearchCategory||null,details:place||null,reply:state.moduleSearchReply||'',routeContext:state.routeSearchContext||null};
}
function returnToNavigationSource(){
 const source=state.navigationReturnContext;if(!source)return;
 finishRouteSearchLoading();clearDedicatedRouteResults();
 document.getElementById('returnToSearchSource')?.remove();
 if(state.busy){state.conversationGeneration++;state.busy=false}
 closeLongChoice();closeRouteMap(false);cancelTransitAccess(true);
 state.navigationReturnContext=null;state.routeSearchContext=source.routeContext;
 state.pendingTravelMode=null;state.pendingRouteDestination=null;
 if(source.view==='assistant'){switchConversationModule('assistant');if(source.encyclopediaArticle){state.encyclopediaTripActive=false;openEncyclopediaCard(source.encyclopediaArticle,NaN)}return}
 if(!['maps','travel'].includes(source.module)){switchConversationModule('assistant');return}
 switchConversationModule(source.module);
 state.moduleSearchResults=Array.isArray(source.results)?source.results.slice():[];state.moduleSearchCategory=source.choice||null;state.moduleSearchReply=source.reply||'';
 document.querySelector('.module-quick-sheet')?.classList.remove('results-mode');
 $('moduleLayerBody').style.cssText='';
 updateQuickLayerGeometry();
 if(state.moduleSearchResults.length){
  $('moduleQuickLayer').classList.add('open');$('moduleQuickLayer').setAttribute('aria-hidden','false');
  renderModulePlaces(state.moduleSearchResults);
 }else{
  $('moduleQuickLayer').classList.remove('open');$('moduleQuickLayer').setAttribute('aria-hidden','true');
  state.moduleSearchCategory=null;renderModuleLandingChoices();
 }
}
