let scienceJourney={stage:'subjects',subject:null,level:null,grade:null,specialty:null,topic:null};
let scienceVoiceActive=false,scienceLastReply='',scienceRequestController=null;
function scienceSubjectInfo(){return SCIENCE_SUBJECTS.find(s=>s.id===scienceJourney.subject)||null}
function scienceTopicAllowedGrade(topic){
 if(scienceJourney.level==='advanced')return true;
 const stageAllows=()=>scienceJourney.level==='intermediate'?
  topic.minLevel!=='advanced':topic.minLevel==='beginner';
 if(educationCountrySelection.code!=='RO')return stageAllows();
 const grade=Number(scienceJourney.grade),id=topic.id,sub=scienceJourney.subject;
 if(!Number.isInteger(grade)||grade<5)return stageAllows();
 const school={
 physics:{
  6:['units','kinematics','energy','heat','fluids'],
  7:['units','kinematics','dynamics','energy','fluids','electric'],
  8:['units','energy','heat','electric','optics','waves']
 },
 chemistry:{
  7:['fundamentals','atomic','periodic','bonding','reactions'],
  8:['reactions','inorganic','solutions','acids','atomic','periodic'],
  9:['fundamentals','atomic','periodic','bonding','reactions','solutions','inorganic'],
  10:['reactions','solutions','acids','organic','inorganic'],
  11:['organic','physical','electrochem','analytical'],
  12:['organic','physical','electrochem','biochemistry','analytical']
 },
 biology:{
  5:['cells','plants','ecology','evolution'],
  6:['cells','anatomy','plants','ecology','evolution'],
  7:['anatomy','genetics','cells','ecology','evolution'],
  8:['anatomy','genetics','ecology','evolution','plants'],
  9:['cells','biomolecules','genetics','evolution','ecology'],
  10:['anatomy','homeostasis','genetics','ecology'],
  11:['genetics','cells','biomolecules','microbes','methods'],
  12:['genetics','anatomy','homeostasis','microbes','methods']
 }
 };
 if(sub==='astronomy')return stageAllows(); // optional general learning, never imply a compulsory school syllabus
 const allowed=school[sub]?.[grade];
 return allowed?allowed.includes(id):stageAllows(); // unverified grades must not expose higher-level-only topics
}
function scienceTopicChoices(){
 const subject=scienceJourney.subject;
 if(!['physics','chemistry','biology','astronomy'].includes(subject))return SCIENCE_OTHER_TOPICS[subject]||[];
 const topics=subject==='physics'?PHYSICS_TOPIC_DATA:subject==='biology'?BIOLOGY_TOPIC_DATA:subject==='astronomy'?ASTRONOMY_TOPIC_DATA:CHEMISTRY_TOPIC_DATA;
 const specializations=subject==='physics'?PHYSICS_SPECIALTY_DATA:subject==='biology'?BIOLOGY_SPECIALTY_DATA:subject==='astronomy'?ASTRONOMY_SPECIALTY_DATA:CHEMISTRY_SPECIALTY_DATA;
 if(scienceJourney.level!=='advanced'||!scienceJourney.specialty)return topics.filter(x=>!x.specialty&&scienceTopicAllowedGrade(x));
 const track=specializations.find(x=>x.id===scienceJourney.specialty);
 return topics.filter(x=>x.specialty===scienceJourney.specialty||
  (!x.specialty&&(track?.core||[]).includes(x.id)));
}
function scienceTopicInfo(){return scienceTopicChoices().find(x=>x.id===scienceJourney.topic)||null}
function scienceLevelInfo(){return CHEMISTRY_LEVEL_DATA.find(x=>x.id===scienceJourney.level)||null}
function scienceStopRequest(){
 if(scienceRequestController){scienceRequestController.abort();scienceRequestController=null}
}
function scienceVoiceStop(){
 if(scienceVoiceActive&&pocketNativeVoiceAvailable())pocketNativeVoiceSend({action:'stopListen'});
 scienceVoiceActive=false;
 $('scienceDictation')?.setAttribute('aria-pressed','false');
}
function scienceBack(){
 const current=scienceJourney.stage;
 scienceVoiceStop();scienceStopRequest();
 if(current==='workspace')scienceJourney.stage='topics';
 else if(current==='topics')scienceJourney.stage=(['physics','chemistry','biology','astronomy'].includes(scienceJourney.subject)&&scienceJourney.level==='advanced')?'specialties':'levels';
 else if(current==='specialties')scienceJourney.stage='levels';
 else if(current==='levels')scienceJourney.stage='subjects';
 else if(current==='grade')scienceJourney.stage='levels';
 else {renderLearningSubjects();return}
 scienceJourneyShowChoices(scienceJourney.stage);
}
function scienceEditorGrow(editor){
 if(!editor?.isConnected)return;
 const vh=window.visualViewport?.height||window.innerHeight;
 const min=editor.value.trim()?Math.max(100,Math.min(148,vh*.22)):Math.max(92,Math.min(112,vh*.17));
 const max=Math.max(min,Math.min(360,vh*.39));
 editor.style.setProperty('height','auto','important');
 const required=editor.scrollHeight+5;
 // Progressive growth follows content; the cap prevents the editor obscuring actions.
 const target=Math.min(max,Math.max(min,required));
 editor.style.setProperty('max-height',Math.ceil(max)+'px','important');
 editor.style.setProperty('height',Math.ceil(target)+'px','important');
 editor.style.overflowY=required>max?'auto':'hidden';
}
function scienceFitViewport(){
 const page=document.querySelector('main.page'),root=$('view-module');
 if(!page||!root?.classList.contains('learning-science')||!root.classList.contains('active')){
  page?.classList.remove('science-keyboard-visible');
  page?.style.removeProperty('--science-content-height');
  return;
 }
 const focus=document.activeElement?.id==='scienceEducationText';
 page.classList.toggle('science-keyboard-visible',focus);
 if(!focus){
  // The normal flex page is already bounded by the header and bottom navigation.
  // Giving it an additional JS-computed fixed height previously double-subtracted chrome.
  page.style.removeProperty('--science-content-height');
  return;
 }
 const viewport=window.visualViewport;
 const visibleBottom=viewport?viewport.offsetTop+viewport.height:window.innerHeight;
 const pageTop=page.getBoundingClientRect().top;
 const navTop=document.querySelector('.bottom-nav')?.getBoundingClientRect().top;
 const usableBottom=Number.isFinite(navTop)&&navTop>pageTop&&navTop<visibleBottom?navTop:visibleBottom;
 page.style.setProperty('--science-content-height',Math.max(130,Math.floor(usableBottom-pageTop-8))+'px');
 // Let the page, not the window or the textarea's ancestor, follow the input.
 const editor=document.getElementById('scienceEducationText');
 if(editor&&document.activeElement===editor){
  requestAnimationFrame(()=>{
   if(document.activeElement!==editor)return;
   const r=editor.getBoundingClientRect();
   const bottom=Math.min(usableBottom,viewport?viewport.offsetTop+viewport.height:window.innerHeight);
   if(r.top>=bottom-90)page.scrollTop+=r.top-(bottom-100);
   else if(r.bottom>bottom-8&&r.top<bottom-90)page.scrollTop+=Math.min(r.bottom-bottom+12,Math.max(0,r.height-80));
  });
 }
}
window.addEventListener('resize',scienceFitViewport,{passive:true});
window.visualViewport?.addEventListener('resize',scienceFitViewport,{passive:true});
