function physicsTheoryOpen(){
 document.getElementById('physicsTheoryDialog')?.remove();
 const dialog=document.createElement('dialog');dialog.id='physicsTheoryDialog';dialog.className='education-theory-dialog physics-theory-dialog';
 const header=document.createElement('div');header.className='education-theory-head';
 const heading=document.createElement('h2');heading.textContent=learningLabel('Fizică · Teorie','Physics · Theory');
 const back=document.createElement('button');back.type='button';back.className='secondary-btn';
 back.textContent=learningLabel('← Revenire','← Back');back.onclick=()=>dialog.close();
 header.append(heading,back);
 const chapter=scienceJourney.topic,level=scienceJourney.level;
 const rank={beginner:0,intermediate:1,medium:1,advanced:2};
 const entries=EDUCATION_THEORY_DATA.filter(x=>x.subject==='physics'&&(!chapter||x.topic===chapter||(!x.topic&&chapter==='dynamics'))&&rank[x.level]<=rank[level]);
 const search=document.createElement('input');search.type='search';search.autocomplete='off';
 search.placeholder=learningLabel('Caută de la prima literă…','Search from the first letter…');
 search.setAttribute('aria-label',learningLabel('Caută lecție de fizică','Search physics lesson'));
 const list=document.createElement('div');list.className='physics-theory-list';
 const detail=document.createElement('section');detail.className='physics-theory-detail';detail.hidden=true;
 function show(item){
  detail.replaceChildren();
  const title=document.createElement('h3');title.textContent=item.title;
  const statement=document.createElement('p');statement.textContent=item.statement;
  const formula=document.createElement('p');formula.className='education-theory-formula';formula.textContent=item.formula;
  const goBack=document.createElement('button');goBack.type='button';goBack.className='secondary-btn';
  goBack.textContent=learningLabel('← La lecții','← Lessons');
  goBack.onclick=()=>{detail.hidden=true;list.hidden=false;search.hidden=false};
  detail.append(goBack,title,statement,formula);
  const kind=physicsVisualKind(item.title,chapter);
  if(kind)detail.append(physicsVisualBuild(kind));
  detail.hidden=false;list.hidden=true;search.hidden=true;
 }
 function render(){
  list.replaceChildren();
  const q=educationTheoryClean(search.value);
  let matches=entries;
  if(q)matches=entries.filter(x=>educationTheoryClean(x.title+' '+x.aliases.join(' ')).includes(q)).slice(0,4);
  if(!matches.length){const p=document.createElement('p');p.textContent=learningLabel('Nicio lecție pentru acest termen.','No matching lesson.');list.append(p)}
  for(const item of matches){
   const btn=document.createElement('button');btn.type='button';btn.className='secondary-btn chemistry-curriculum-row';
   btn.textContent=item.title;btn.onclick=()=>show(item);list.append(btn);
  }
 }
 search.addEventListener('input',render);
 dialog.append(header,search,list,detail);
 dialog.addEventListener('close',()=>dialog.remove());
 document.body.append(dialog);render();
 try{dialog.showModal()}catch{dialog.setAttribute('open','')}
}


function astronomyVisualKind(question,topic){
 const q=educationTheoryClean(question);
 if(/tranzit|exoplanet/.test(q)||topic==='exoplanets'||topic==='special-planetary')return 'transit';
 if(/paralax|distanta|parsec/.test(q)||topic==='distances'||topic==='special-instruments')return 'parallax';
 if(/orbita|kepler|gravitat|evadare/.test(q)||topic==='gravity'||topic==='special-dynamics')return 'orbit';
 if(/hubble|cosmolog|expansiune|redshift|rosu/.test(q)||topic==='cosmology'||topic==='special-cosmo')return 'cosmos';
 if(/spectr|stele|stea|diagrama hr/.test(q)||topic==='stars'||topic==='special-stellar')return 'hr';
 if(/telescop|difract|observ/.test(q)||topic==='observations')return 'telescope';
 if(/galax|spiral/.test(q)||topic==='galaxies'||topic==='special-galactic')return 'galaxy';
 return topic==='solar'||topic==='sky'?'solar':null;
}
function astronomyVisualBuild(kind){
 if(!kind)return null;
 const names={solar:['Sistem solar · schematic','Solar system · schematic'],orbit:['Orbită eliptică · model','Elliptical orbit · model'],parallax:['Paralaxă · geometrie','Parallax · geometry'],hr:['Diagrama H–R · schematic','H–R diagram · schematic'],transit:['Tranzit planetar · model','Planet transit · model'],cosmos:['Expansiunea cosmică · schematic','Cosmic expansion · schematic'],telescope:['Telescop · raze','Telescope · rays'],galaxy:['Galaxie spirală · schematic','Spiral galaxy · schematic']};
 const section=document.createElement('section');section.className='physics-visual astronomy-visual';
 const title=document.createElement('h3');title.textContent=learningLabel(...names[kind]);section.append(title);
 const svg=document.createElementNS('http://www.w3.org/2000/svg','svg');svg.setAttribute('viewBox','0 0 360 210');svg.setAttribute('role','img');svg.setAttribute('aria-label',title.textContent);section.append(svg);
 const add=(tag,attrs,txt)=>{const n=document.createElementNS('http://www.w3.org/2000/svg',tag);for(const [k,v] of Object.entries(attrs||{}))n.setAttribute(k,String(v));if(txt!==undefined)n.textContent=txt;svg.append(n);return n};
 const line=(x1,y1,x2,y2)=>add('line',{x1,y1,x2,y2,stroke:'#9ddff3','stroke-width':2});
 const circle=(x,y,r,color)=>add('circle',{cx:x,cy:y,r,fill:color});
 const label=(x,y,v)=>add('text',{x,y,fill:'#eaf8ff','font-size':12},v);
 if(kind==='solar'){
  circle(40,105,17,'#ffd56f');label(17,147,'Soare');
  [55,83,115,150,192,236,282].forEach((x,i)=>{circle(x+46,105,3+i*.6,['#9dc7ff','#ffbd95','#69a7ed','#e6b396','#edc88b','#aec6df','#79a6d9'][i]);line(57,105,x+40,105)});
  label(180,182,'schematic · distanțe neproporționale');
 }else if(kind==='orbit'){
  add('ellipse',{cx:180,cy:106,rx:140,ry:70,fill:'none',stroke:'#8eddef','stroke-width':2});circle(95,106,13,'#ffcf73');circle(305,143,7,'#9bb9f5');line(95,106,305,143);label(67,93,'focar');label(295,165,'corp');label(158,25,'orbită eliptică');
 }else if(kind==='parallax'){
  circle(180,22,6,'#ffebad');circle(55,175,8,'#a9bffa');circle(305,175,8,'#a9bffa');line(55,175,180,22);line(305,175,180,22);line(55,175,305,175);label(185,28,'stea');label(116,193,'bază orbitală');
 }else if(kind==='hr'){
  line(45,18,45,185);line(45,185,330,185);label(48,17,'Luminozitate ↑');label(163,202,'Temperatură → scade');
  for(let i=0;i<11;i++){circle(65+i*23,40+i*12,3+i*.25,'#acdff2')}
  circle(84,155,14,'#eb9f8c');circle(294,44,14,'#ffdb9b');label(150,67,'secvența principală');
 }else if(kind==='transit'){
  circle(118,94,52,'#ffd28b');circle(139,95,11,'#223652');
  line(200,54,200,165);line(200,165,343,165);
  add('path',{d:'M207 70 L245 70 Q265 70 272 113 Q279 70 299 70 L339 70',fill:'none',stroke:'#88dcec','stroke-width':3});
  label(219,184,'timp →');label(214,38,'flux normalizat');
 }else if(kind==='cosmos'){
  [0,1,2].forEach((n)=>{const cx=65+n*110;circle(cx,105,5+n*3,'#b9dfff');for(let j=0;j<4;j++)circle(cx+Math.cos(j*1.57)*(17+n*9),105+Math.sin(j*1.57)*(17+n*9),3,'#d9bdff');if(n<2)label(cx+44,110,'→')});
  label(72,183,'scara cosmică crește (schematic)');
 }else if(kind==='telescope'){
  add('path',{d:'M85 85 L155 58 L155 152 L85 125 Z',fill:'none',stroke:'#9ddff3','stroke-width':2});line(155,58,222,105);line(155,152,222,105);line(222,105,300,105);label(63,60,'apertură');label(220,130,'focar');
 }else if(kind==='galaxy'){
  circle(180,107,16,'#ffd8ac');for(let arm=0;arm<3;arm++)for(let i=0;i<65;i++){const t=i*.12+arm*2.094,r=12+i*1.8;circle(180+r*Math.cos(t),107+r*.48*Math.sin(t),1.1,'#b4c9fa')}label(105,188,'spirală · fără scară');
 }
 return section;
}

function astronomyOrbit3DOpen(){
 document.getElementById('astronomy3DDialog')?.remove();
 const dialog=document.createElement('dialog');dialog.id='astronomy3DDialog';dialog.className='education-theory-dialog physics-theory-dialog';
 const header=document.createElement('div');header.className='education-theory-head';
 const heading=document.createElement('h2');heading.textContent=learningLabel('Orbite · model 3D interactiv','Orbits · interactive 3D model');
 const back=document.createElement('button');back.type='button';back.className='secondary-btn';back.textContent=learningLabel('← Revenire','← Back');back.onclick=()=>dialog.close();header.append(heading,back);
 const note=document.createElement('p');note.textContent=learningLabel('Proiecție 3D educativă. Mărimile, perioadele și distanțele nu sunt la scară.','Educational 3D projection. Sizes, periods and distances are not to scale.');
 const frame=document.createElement('div');frame.className='physics-visual';frame.style.maxWidth='100%';frame.style.overflow='hidden';
 const svg=document.createElementNS('http://www.w3.org/2000/svg','svg');svg.setAttribute('viewBox','0 0 360 240');svg.setAttribute('role','img');svg.setAttribute('aria-label',learningLabel('Planete și orbite rotibile','Rotatable planets and orbits'));frame.append(svg);
 const controls=document.createElement('div');controls.className='science-work-tools';
 const make=(ro,en,min,max,value)=>{const box=document.createElement('label');box.textContent=learningLabel(ro,en);const input=document.createElement('input');input.type='range';input.min=min;input.max=max;input.value=value;input.setAttribute('aria-label',box.textContent);box.append(input);controls.append(box);return input};
 const turn=make('Rotire','Rotation','0','360','28'),tilt=make('Înclinare','Tilt','0','85','48'),zoom=make('Zoom','Zoom','50','140','100');
 const ns='http://www.w3.org/2000/svg';
 const node=(tag,attrs)=>{const el=document.createElementNS(ns,tag);for(const [k,v] of Object.entries(attrs))el.setAttribute(k,String(v));svg.append(el);return el};
 const project=(x,y,z)=>{const a=Number(turn.value)*Math.PI/180,b=Number(tilt.value)*Math.PI/180,k=Number(zoom.value)/100;const xx=x*Math.cos(a)-y*Math.sin(a),yy=x*Math.sin(a)+y*Math.cos(a);return [180+xx*k,120+(yy*Math.cos(b)-z*Math.sin(b))*k]};
 const render=()=>{svg.replaceChildren();node('circle',{cx:180,cy:120,r:11,fill:'#ffd477'});
  for(const [radius,size,color,phase] of [[38,3,'#bfc6d4',.2],[66,5,'#e2ba83',1.7],[91,6,'#79bafd',3.4],[113,4,'#e39a7a',5.2]]){
   let path='';for(let i=0;i<=96;i++){const a=i*Math.PI*2/96;const p=project(radius*Math.cos(a),radius*Math.sin(a),0);path+=(i?' L':'M')+p[0].toFixed(2)+' '+p[1].toFixed(2)}
   node('path',{d:path,stroke:'#7899b7','stroke-width':1.3,fill:'none'});
   const pos=project(radius*Math.cos(phase),radius*Math.sin(phase),0);node('circle',{cx:pos[0],cy:pos[1],r:size,fill:color});
  }
 };
 const interact=()=>render();turn.addEventListener('input',interact);tilt.addEventListener('input',interact);zoom.addEventListener('input',interact);
 let dragX=null;svg.style.touchAction='none';
 svg.addEventListener('pointerdown',e=>{dragX=e.clientX;svg.setPointerCapture?.(e.pointerId)});
 svg.addEventListener('pointermove',e=>{if(dragX===null)return;turn.value=String((Number(turn.value)+e.clientX-dragX+360)%360);dragX=e.clientX;render()});
 svg.addEventListener('pointerup',()=>dragX=null);svg.addEventListener('pointercancel',()=>dragX=null);
 dialog.append(header,note,frame,controls);dialog.addEventListener('close',()=>dialog.remove());document.body.append(dialog);render();try{dialog.showModal()}catch{dialog.setAttribute('open','')};
}

