 const pad=Math.max(1,(yMax-yMin)*.08);yMin-=pad;yMax+=pad;
 if(yMax-yMin<8){const mid=(yMax+yMin)/2;yMin=mid-4;yMax=mid+4}
 const width=420,height=274,left=45,right=12,top=18,bottom=37;
