/* Maps and hotels regain their own landing options. Keep existing search logic. */
function renderModuleLandingChoices(){
 finishRouteSearchLoading();clearDedicatedRouteResults();
 document.querySelector('.module-quick-sheet')?.classList.remove('mode-choice-screen');
 document.getElementById('returnToSearchSource')?.remove();
 const view=$('view-module'),host=$('moduleContent');
 view.classList.add('module-landing');
 const choices=MODULE_QUICK_CHOICES[state.currentModule]||[];
 const locale=window.__pocketEuropeanUiText?.[state.language];
 const grid=document.createElement('div');grid.className='module-landing-grid';
 choices.forEach((choice,index)=>{
  const card=document.createElement('button');card.type='button';card.className='module-landing-choice';
  const emoji=document.createElement('span');emoji.className='module-landing-icon';emoji.textContent=choice.icon;
  const title=document.createElement('strong');title.textContent=localizedQuickChoiceTitle(choice);
  const note=document.createElement('small');
  note.textContent=locale?.quickChoiceDetails?.[choice.title]||
   (state.language==='ro'?choice.description||'':state.language==='en'?(choice.kind==='transit'?quickUiText().descTransit:choice.kind==='walking'?quickUiText().descWalking:quickUiText().descPlaces):'');
  card.append(emoji,title);if(note.textContent)card.append(note);
  card.addEventListener('click',()=>{
   openModuleLandingAction(choice);
  });grid.append(card);
 });
 host.replaceChildren(grid);$('moduleLead').textContent='';
 requestAnimationFrame(educationFitMenuViewport);
}
function updateQuickLayerGeometry(){
 const header=document.querySelector('.app-header'),nav=document.querySelector('.bottom-nav');
 const top=header?Math.ceil(header.getBoundingClientRect().bottom+6):90;
 const bottom=nav?Math.ceil(window.innerHeight-nav.getBoundingClientRect().top+6):100;
 const layer=$('moduleQuickLayer');
 if(layer){layer.style.setProperty('--quick-top',Math.max(0,top)+'px');layer.style.setProperty('--quick-bottom',Math.max(0,bottom)+'px')}
}
window.addEventListener('resize',updateQuickLayerGeometry,{passive:true});
window.addEventListener('orientationchange',updateQuickLayerGeometry,{passive:true});
function openModuleLandingAction(choice){
 if(!choice||!['maps','travel'].includes(state.currentModule))return;
 state.navigationReturnContext=null;state.lastQuickPlace=null;
 state.moduleSearchCategory=null;state.moduleSearchResults=[];state.moduleSearchReply='';state.moduleSearchScrollTop=0;state.moduleSearchBodyScrollTop=0;
 document.querySelector('.module-quick-sheet')?.classList.remove('details-mode','results-mode');
 $('moduleLayerBody').style.cssText='';
 updateQuickLayerGeometry();
 $('moduleQuickLayer').classList.add('open');$('moduleQuickLayer').setAttribute('aria-hidden','false');
 // Shared A→B entry point. Retain existing multimodal public transport and road adapters.
 if(choice.kind==='walking')showWalkingQuickDestination(choice);
 else if(choice.mixedJourney)showJourneyMode(choice);
 else if(choice.kind==='transit')showPreciseJourney({...choice,journeyMode:'transit'});
 else runModuleSearch(choice);
}
