// Official sources for UK-wide journeys when no licensed national itinerary is confirmed.
const UK_PLANNING_TEXT={
 ro:['Verifică orarele la operatori','Surse oficiale pentru trenuri și transport regional. Nu au fost verificate plecări în aplicație.'],
 en:['Check live timetables','Official train and regional transport planners. No departures have been verified in the app.'],
 fr:['Vérifier les horaires','Planificateurs officiels de trains et de transports régionaux. Aucun départ vérifié dans l’application.'],
 de:['Fahrpläne prüfen','Offizielle Fahrpläne für Züge und Nahverkehr. In der App sind keine Abfahrten bestätigt.'],
 it:['Controlla gli orari','Pianificatori ufficiali di treni e trasporti regionali. Nessuna partenza verificata nell’app.'],
 es:['Consultar horarios','Planificadores oficiales de trenes y transporte regional. La aplicación no ha confirmado salidas.'],
 pt:['Consultar horários','Planeadores oficiais de comboios e transportes regionais. A aplicação não confirmou partidas.'],
 nl:['Controleer dienstregelingen','Officiële planners voor trein en regionaal vervoer. In de app zijn geen vertrekken bevestigd.'],
 ru:['Проверьте расписание','Официальные планировщики поездов и местного транспорта. Отправления в приложении не подтверждены.'],
 pl:['Sprawdź rozkłady jazdy','Oficjalne planery pociągów i transportu regionalnego. Odjazdy nie są potwierdzone w aplikacji.']
};
function appendOfficialUKJourneySources(data,host){
 if(!Array.isArray(data?.planning_links)||!data.planning_links.length||!host)return false;
 const words=UK_PLANNING_TEXT[state.language]||UK_PLANNING_TEXT.en;
 const area=document.createElement('section');area.className='uk-transit-official-sources';
 const title=document.createElement('h3');title.textContent=words[0];
 const note=document.createElement('p');note.textContent=words[1];
 area.append(title,note);
 let count=0;
 const allowed=new Set(['www.nationalrail.co.uk','www.traveline.info','tfgm.com']);
 for(const entry of data.planning_links.slice(0,5)){
  const name=String(entry?.name||'').slice(0,75);
  let link;try{link=new URL(String(entry?.url||''))}catch{continue}
  if(link.protocol!=='https:'||!allowed.has(link.hostname)||!name)continue;
  const a=document.createElement('a');a.className='transit-choice-action uk-transit-source-link';
  a.textContent=name;a.href=link.href;a.target='_blank';a.rel='noopener noreferrer';
  area.append(a);count++;
 }
 if(!count)return false;
 host.append(area);return true;
}
function moduleStatus(text){document.querySelector('.module-quick-sheet')?.classList.remove('results-mode');const body=$('moduleLayerBody');body.innerHTML='';const status=document.createElement('div');status.className='module-search-status';status.setAttribute('role','status');status.textContent=text;body.append(status)}
function formatDistance(meters){const n=Number(meters);if(!Number.isFinite(n)||n<0)return ({ro:'Distanță indisponibilă',en:'Distance unavailable',fr:'Distance indisponible',de:'Entfernung nicht verfügbar',it:'Distanza non disponibile',es:'Distancia no disponible',pt:'Distância indisponível',nl:'Afstand niet beschikbaar',ru:'Расстояние неизвестно',pl:'Odległość niedostępna'})[state.language]||'Distance unavailable';if(n<1000)return Math.round(n)+' m';return (n/1000).toLocaleString(({ro:'ro-RO',en:'en-GB',fr:'fr-FR',de:'de-DE',it:'it-IT',es:'es-ES',pt:'pt-PT',nl:'nl-NL',ru:'ru-RU',pl:'pl-PL'})[state.language]||'en-GB',{maximumFractionDigits:1})+' km'}
function placeResultIcon(place){const special={shopping_fashion:'🛍️',beauty_services:'💇',home_goods:'🏡',appliances:'🔌',furniture:'🛋️',diy_garden:'🛠️',car_dealers:'🚘'};if(special[String(place.type||'')])return special[String(place.type||'')];const value=(String(place.type||'')+' '+String(place.name||'')).toLowerCase();if(/petrol|fuel|gas station|benzin|esso|shell|texaco|costco fuel/.test(value))return '⛽';if(/restaurant|cafe|coffee|food|restaurant|restaurant|takeaway|pub|bar/.test(value))return '🍽️';if(/hotel|motel|guest.?house|accommodation/.test(value))return '🏨';if(/supermarket|grocery|shop|store|market/.test(value))return '🛒';if(/bus stop|bus station|train station|railway|metro|underground/.test(value))return '🚉';if(/hospital|clinic|doctor|pharmacy/.test(value))return '🏥';if(/parking|car park/.test(value))return '🅿️';if(/toilet|restroom/.test(value))return '🚻';if(/car wash|wash/.test(value))return '🚿';return '📍'}
